package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen2Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testFactorialLog_NegativeInput() {
        try {
            MathUtils.factorialLog(-1);
            org.junit.Assert.fail("Expected IllegalArgumentException for n < 0");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialLog_Zero() {
        // log(0!) = log(1) = 0
        assertEquals(0.0, MathUtils.factorialLog(0), DELTA);
    }

    @Test
    public void testFactorialLog_One() {
        // log(1!) = log(1) = 0
        assertEquals(0.0, MathUtils.factorialLog(1), DELTA);
    }

    @Test
    public void testFactorialLog_Two() {
        // log(2!) = log(2)
        assertEquals(Math.log(2.0), MathUtils.factorialLog(2), DELTA);
    }

    @Test
    public void testFactorialLog_Three() {
        // log(3!) = log(1 * 2 * 3) = log(2) + log(3)
        assertEquals(Math.log(2.0) + Math.log(3.0), MathUtils.factorialLog(3), DELTA);
    }

    @Test
    public void testFactorialLog_LargeValue() {
        // Testing a slightly larger value to ensure loop coverage
        int n = 10;
        double expected = 0;
        for (int i = 2; i <= n; i++) {
            expected += Math.log((double) i);
        }
        assertEquals(expected, MathUtils.factorialLog(n), DELTA);
    }
}
